// Intended function: grow or regress flora from local environmental inputs while keeping remote flora compact as patch aggregates.
#include "world/FloraSystem.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{FloraArchetype generateFloraArchetype(std::uint64_t p,std::uint32_t o){auto s=mix64(p^mix64(o)^0x464C4F5241ULL);auto u=[&](int n){return float((mix64(s^n)>>40)&0xffffff)/float(0xffffff);};FloraArchetype a;a.speciesId=mix64(s^1);a.form=FloraForm(std::uint8_t(u(2)*8)%8);a.minTemp=-45+u(3)*55;a.maxTemp=a.minTemp+15+u(4)*55;a.minMoisture=u(5)*.6f;a.maxMoisture=std::min(1.f,a.minMoisture+.25f+u(6)*.65f);a.growthRate=.01f+u(7)*.2f;a.maxScale=.2f+u(8)*12;a.harvestYield=.1f+u(9)*8;a.materialItemId=5000+std::uint32_t(o%1000);a.edible=u(10)<.25f;a.medicinal=u(11)<.15f;a.hazardous=u(12)<.12f;return a;}void advanceFloraPatch(FloraPatch&p,const FloraArchetype&a,float t,float m,float l,float dt){float temp=(t>=a.minTemp&&t<=a.maxTemp)?1.f:0.f;float moist=(m>=a.minMoisture&&m<=a.maxMoisture)?1.f:.25f;float growth=a.growthRate*temp*moist*std::clamp(l,0.f,1.f)*std::clamp(p.nutrient,0.f,1.f)*dt;float decay=(1-temp)*.05f*dt;p.biomass=std::clamp(p.biomass+growth-decay,0.f,a.maxScale);p.nutrient=std::clamp(p.nutrient-growth*.05f,0.f,1.f);p.water=std::clamp(p.water-growth*.04f,0.f,1.f);}}
